cd "D:/DevOpsAutopilot/video-29-db-migration/ai-db-migration/workspace" && node -e '
const steps = [];
const lockLoop = (body) => `DO $$ DECLARE tries int := 0; BEGIN
  PERFORM set_config(\x27lock_timeout\x27, \x27300ms\x27, true);
  LOOP
    BEGIN
      LOCK TABLE orders IN ACCESS EXCLUSIVE MODE;
      EXIT;
    EXCEPTION WHEN lock_not_available THEN
      tries := tries + 1;
      IF tries >= 200 THEN RAISE; END IF;
      PERFORM pg_sleep(0.2 + random() * 0.5);
    END;
  END LOOP;
${body}
END $$;`;
steps.push({note: "Create the trigger function that copies customer_id into the new bigint column on every insert/update of customer_id. No lock on orders.",
  sql: "CREATE OR REPLACE FUNCTION orders_customer_id_sync() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN NEW.customer_id_new := NEW.customer_id; RETURN NEW; END $f$;"});
steps.push({note: "In one short transaction (lock taken with a 300 ms lock_timeout, retried): add nullable customer_id_new bigint (metadata only, no rewrite), the sync trigger, and NOT VALID checks that it is non-null and equal to customer_id. From now on every new row is written to both columns.",
  sql: lockLoop(`  ALTER TABLE orders ADD COLUMN customer_id_new bigint;
  CREATE TRIGGER orders_customer_id_sync BEFORE INSERT OR UPDATE OF customer_id ON orders
    FOR EACH ROW EXECUTE FUNCTION orders_customer_id_sync();
  ALTER TABLE orders
    ADD CONSTRAINT orders_customer_id_new_nn CHECK (customer_id_new IS NOT NULL) NOT VALID,
    ADD CONSTRAINT orders_customer_id_new_eq CHECK (customer_id_new = customer_id) NOT VALID;`)});
const BATCH = 50000, CHUNK = 1000000, MAXID = 10000000;
for (let c = 0; c < MAXID; c += CHUNK) {
  const stmts = [];
  for (let s = c; s < c + CHUNK; s += BATCH)
    stmts.push(`UPDATE orders SET customer_id_new = customer_id WHERE id > ${s} AND id <= ${s + BATCH} AND customer_id_new IS NULL;`);
  steps.push({note: `Backfill ids ${c + 1}..${c + CHUNK} in ${CHUNK / BATCH} batches of ${BATCH} rows, each its own short transaction (row locks only on old rows the app never updates).`, sql: stmts.join(" ")});
  steps.push({note: "Vacuum so the dead row versions from this chunk are reused and the table does not double in size. Does not block reads or writes.", sql: "VACUUM orders;"});
}
steps.push({note: "Backfill any rows above id 10,000,000 that were inserted before the trigger existed.",
  sql: `UPDATE orders SET customer_id_new = customer_id WHERE id > ${MAXID} AND customer_id_new IS NULL;`});
steps.push({note: "Validate both checks (SHARE UPDATE EXCLUSIVE: app reads and writes keep running). Fails, and stops the plan before any destructive step, if any row is NULL or differs from customer_id.",
  sql: "ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_new_nn; ALTER TABLE orders VALIDATE CONSTRAINT orders_customer_id_new_eq;"});
steps.push({note: "Refresh planner statistics so the new column keeps the same estimates for the /customer query.", sql: "VACUUM ANALYZE orders;"});
steps.push({note: "Swap in one short transaction (lock with 300 ms lock_timeout, retried): SET NOT NULL (no table scan, proven by the validated check), drop trigger and checks, drop the old integer column, rename customer_id_new to customer_id. Catalog-only, milliseconds.",
  sql: lockLoop(`  ALTER TABLE orders ALTER COLUMN customer_id_new SET NOT NULL;
  DROP TRIGGER orders_customer_id_sync ON orders;
  ALTER TABLE orders DROP CONSTRAINT orders_customer_id_new_nn, DROP CONSTRAINT orders_customer_id_new_eq;
  ALTER TABLE orders DROP COLUMN customer_id;
  ALTER TABLE orders RENAME COLUMN customer_id_new TO customer_id;`)});
steps.push({note: "Drop the now-unused trigger function.", sql: "DROP FUNCTION orders_customer_id_sync();"});
steps.push({note: "Verify: orders.customer_id is bigint NOT NULL and has no NULLs.",
  sql: `DO $$ BEGIN
  IF (SELECT format_type(atttypid, atttypmod) || \x27/\x27 || attnotnull FROM pg_attribute
      WHERE attrelid = \x27orders\x27::regclass AND attname = \x27customer_id\x27 AND NOT attisdropped) IS DISTINCT FROM \x27bigint/true\x27
  THEN RAISE EXCEPTION \x27orders.customer_id is not bigint NOT NULL\x27; END IF;
END $$;`});
require("fs").writeFileSync("plans/live-customer-bigint-2.json", JSON.stringify({task: "customer-bigint", steps}, null, 2) + "\n");
console.log(steps.length);
' && node -e 'const p=require("./plans/live-customer-bigint-2.json"); console.log(p.steps[1].sql); console.log(p.steps[2].sql.slice(0,300)); console.log(p.steps.at(-3).sql)'
